#include <cstdio>
#include <algorithm>
#include <cstring>
#include <queue>

using namespace std;

struct node { int r,c,dis; };

const int dx[4] = {-1,0,1,0};
const int dy[4] = {0,-1,0,1};

queue<node> q;
char s[15];

int n, n1, m, lim;
int a[11][11], b[11][11], d0[11][11];
int capacity[205][205];
bool ok[12][12], okb[12][12];

int pushCap[205][205], pushHeight[205], pushExcess[205];
bool pushActive[205];

int main()
{
    scanf("%d %d", &m, &lim);
    memset(capacity, 0, sizeof(capacity));
    memset(a, 0, sizeof(a));
    memset(b, 0, sizeof(b));
    memset(ok, 0, sizeof(ok));
    memset(d0, 0, sizeof(d0));

    for (int i = 1; i <= m; ++i)
    {
        scanf("%s", s + 1);
        for (int j = 1; j <= m; ++j)
        {
            if (s[j] == 'Z')
            {
                node he;
                he.r = i;
                he.c = j;
                he.dis = 0;
                q.push(he);
            }
            else if (s[j] != 'Y')
            {
                ok[i][j] = true;
                d0[i][j] = lim;
                int k = s[j] - '0';
                if (k > 0)
                {
                    a[i][j] = ++n;
                    capacity[0][n] = k;
                    n1 += k;
                }
            }
        }
    }
    memcpy(okb, ok, sizeof(ok));

    for (int i = 1; i <= m; ++i)
    {
        scanf("%s", s + 1);
        for (int j = 1; j <= m; ++j)
        {
            if (s[j] == 'Z' || s[j] == 'Y')
                continue;
            int k = s[j] - '0';
            if (k > 0)
            {
                b[i][j] = ++n;
                capacity[n][m * m + 1] = k;
            }
        }
    }

    if (n != m * m)
    {
        for (int i = 1; i <= m; ++i)
            for (int j = 1; j <= m; ++j)
                if (b[i][j] > 0)
                {
                    int k = b[i][j];
                    capacity[k][n + 1] = capacity[k][m * m + 1];
                    capacity[k][m * m + 1] = 0;
                }
    }

    int sink = n + 1;
    int V = n + 2;

    while (!q.empty())
    {
        node he = q.front();
        q.pop();
        int i = he.r, j = he.c;
        d0[i][j] = he.dis;
        for (int k = 0; k < 4; ++k)
        {
            if (ok[i + dx[k]][j + dy[k]])
            {
                node e;
                e.r = i + dx[k];
                e.c = j + dy[k];
                e.dis = he.dis + 1;
                q.push(e);
                ok[i + dx[k]][j + dy[k]] = false;
            }
        }
    }

    for (int i = 1; i <= m; ++i)
    {
        for (int j = 1; j <= m; ++j)
        {
            if (a[i][j] == 0)
                continue;
            memcpy(ok, okb, sizeof(okb));
            ok[i][j] = false;
            node he;
            he.r = i;
            he.c = j;
            he.dis = 0;
            q.push(he);
            while (!q.empty())
            {
                node he = q.front();
                q.pop();
                int x = he.r, y = he.c;
                if (b[x][y] > 0 && he.dis <= d0[x][y])
                    capacity[a[i][j]][b[x][y]] = n1;
                if (he.dis + 1 > lim || he.dis >= d0[x][y])
                    continue;
                for (int k = 0; k < 4; ++k)
                {
                    if (ok[x + dx[k]][y + dy[k]])
                    {
                        node e;
                        e.r = x + dx[k];
                        e.c = y + dy[k];
                        e.dis = he.dis + 1;
                        q.push(e);
                        ok[x + dx[k]][y + dy[k]] = false;
                    }
                }
            }
        }
    }

    memcpy(pushCap, capacity, sizeof(capacity));
    memset(pushHeight, 0, sizeof(pushHeight));
    memset(pushExcess, 0, sizeof(pushExcess));
    memset(pushActive, 0, sizeof(pushActive));

    queue<int> act;
    pushHeight[0] = V;

    for (int v = 0; v < V; ++v)
    {
        if (pushCap[0][v] > 0)
        {
            pushExcess[v] = pushCap[0][v];
            pushCap[0][v] = 0;
            pushCap[v][0] += pushExcess[v];
            pushExcess[0] -= pushExcess[v];
            if (v != 0 && v != sink && !pushActive[v])
            {
                pushActive[v] = true;
                act.push(v);
            }
        }
    }

    while (!act.empty())
    {
        int u = act.front();
        act.pop();
        pushActive[u] = false;
        while (pushExcess[u] > 0)
        {
            bool pushed = false;
            for (int v = 0; v < V; ++v)
            {
                if (pushCap[u][v] > 0 && pushHeight[u] == pushHeight[v] + 1)
                {
                    int d = min(pushExcess[u], pushCap[u][v]);
                    pushCap[u][v] -= d;
                    pushCap[v][u] += d;
                    pushExcess[u] -= d;
                    pushExcess[v] += d;
                    if (v != 0 && v != sink && !pushActive[v])
                    {
                        pushActive[v] = true;
                        act.push(v);
                    }
                    pushed = true;
                    if (pushExcess[u] == 0)
                        break;
                }
            }
            if (!pushed)
            {
                int minh = 1000000000;
                for (int v = 0; v < V; ++v)
                    if (pushCap[u][v] > 0)
                        minh = min(minh, pushHeight[v]);
                if (minh == 1000000000)
                    minh = V;
                pushHeight[u] = minh + 1;
            }
        }
    }

    printf("%d\n", pushExcess[sink]);
    return 0;
}
